  'coach.guide.month.softCopy.s2.title': '«План → пустой факт»',
  'coach.guide.month.softCopy.s1.body': 'На полоске листа нажмите «Инструменты» (красная рамка) — не путать с «Ещё» в самой верхней шапке.',
  'coach.guide.month.softCopy.s1.title': 'Откройте «Инструменты»',
  'coach.guide.month.softCopy.blurb': '«Инструменты» → «План → пустой факт»',
  'coach.guide.month.softCopy.title': 'Безопасно: план → только пустой факт',
  'coach.guide.month.history.s1.body': 'В боковой панели «Инструменты» — кнопки ↶ и ↷. Нажмите группу в красной рамке (или ↶). Отменяется последняя правка ячейки в этой вкладке. Работает только пока не закрыли страницу.',
  'coach.guide.month.history.s1.title': 'История правок',
