  'coach.guide.month.history.title': 'Отменить правку (как в Word)',
  'coach.guide.month.mismatchFilter.s1.body': 'В панели «Инструменты» кнопка «Только ≠». Нажмите красную рамку — останутся строки, где план и факт не совпадают. Ещё раз — снова все.',
  'coach.guide.month.mismatchFilter.s1.title': 'Включите фильтр «Только ≠»',
