  'coach.guide.month.fillSelection.s2.body': 'Зажмите Ctrl и кликайте дни (или Ctrl+протянуть по одной строке). Сверху появится «Выбрано N». Затем обычный клик по любой выбранной — пикер кода зальёт все. Esc снимает выделение. На этом шаге достаточно кликнуть клетку.',
