  'coach.guide.hr.addEmployee.s2.title': 'Кнопка «Добавить»',
  'coach.guide.hr.addEmployee.s2.body': 'Нажмите кнопку добавления сотрудника (красная рамка). Откроется карточка: ФИО, должность, бригада и т.д. На уровне «До конца» я проведу до кнопки «Сохранить» в этом окне.',
  'coach.guide.hr.addEmployee.sSalary.title': 'Оклад в карточке',
  'coach.guide.hr.addEmployee.sSalary.body': 'В карточке найдите поле «Оклад, ₾/мес» (красная рамка). Введите сумму на полную ставку и нажмите на рамку. HR и инспектор кадров могут править оклад здесь, не заходя в Финансы.',
  'coach.guide.hr.addEmployee.s3.title': 'Сохраните карточку',
