  'hr.registryImport.hint': `Upload Excel (.xlsx) «EMPLOYEE REGISTRY». Records get: name, badge #, position, phone, email, IBAN (account), salary, contract dates, contract # and labor registry #, links to ID and contracts (Google Drive). Dismissed — status «Dismissed» with date.`,
